"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";
import { Loader2, ScrollText } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { settingsService, type ActivityLog } from "@/lib/api/services/settings.service";

export default function LogsPage() {
  const [logs, setLogs] = useState<ActivityLog[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        setLogs(await settingsService.listActivityLogs());
      } catch (e: any) {
        toast.error(e.message || "Erro ao carregar logs");
      } finally {
        setLoading(false);
      }
    };
    void load();
  }, []);

  return (
    <div className="p-6 space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Logs de actividade</h1>
        <p className="text-muted-foreground">
          Histórico de acções na plataforma da instituição
        </p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <ScrollText className="h-5 w-5" /> Actividade recente
          </CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : logs.length === 0 ? (
            <p className="text-center py-10 text-muted-foreground">
              Ainda não há registos de actividade.
            </p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Data</TableHead>
                  <TableHead>Actor</TableHead>
                  <TableHead>Acção</TableHead>
                  <TableHead>Entidade</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {logs.map((log) => (
                  <TableRow key={log.id}>
                    <TableCell className="whitespace-nowrap">
                      {new Date(log.created_at).toLocaleString("pt-PT")}
                    </TableCell>
                    <TableCell>{log.actor_name || "—"}</TableCell>
                    <TableCell>{log.action}</TableCell>
                    <TableCell>
                      {log.entity_type
                        ? `${log.entity_type}${log.entity_id ? ` #${log.entity_id.slice(0, 8)}` : ""}`
                        : "—"}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
